const opt=(v,sel,l)=>`<option value="${esc(v)}"${v===sel?' selected':''}>${esc(l||v)}</option>`;
const pad=n=>String(n).padStart(2,'0');
const today=()=>{const d=new Date();return d.getFullYear()+'-'+pad(d.getMonth()+1)+'-'+pad(d.getDate())};
const nowT=()=>{const d=new Date();return pad(d.getHours())+':'+pad(d.getMinutes())};
const ym=d=>d.slice(0,7);
const shiftYm=(s,d)=>{const x=new Date(+s.slice(0,4),+s.slice(5)-1+d,1);return x.getFullYear()+'-'+pad(x.getMonth()+1)};
const prevYm=s=>shiftYm(s,-1);
const dim=s=>new Date(+s.slice(0,4),+s.slice(5),0).getDate();
const monthLabel=s=>new Date(+s.slice(0,4),+s.slice(5)-1,1).toLocaleDateString('id-ID',{month:'long',year:'numeric'});
const dateLabel=d=>new Date(d+'T00:00').toLocaleDateString('id-ID',{weekday:'long',day:'numeric',month:'long',year:'numeric'});
