R.rec=()=>`<header class="hd"><h1>Transaksi Rutin</h1><button class="btn" data-act="addrec">+ Rutin</button></header><p class="muted sm">Transaksi rutin diproses otomatis saat DuitKu dibuka (tidak ada server yang berjalan saat browser tertutup). Setiap tanggal hanya dibuat satu kali.</p>
  ${D.recurring.length?D.recurring.map(r=>`<div class="card"><div class="row sp"><div class="row">${ico(r.cat)}<div><b>${esc(r.name)}</b>${r.active===false?' <span class="badge">Nonaktif</span>':''}<br><small class="muted">${{daily:'Harian',weekly:'Mingguan',monthly:'Bulanan'}[r.freq]} · mulai ${esc(r.start)}${r.end?' · sampai '+esc(r.end):''} · ${esc((wal(r.wallet)||{name:'-'}).name)}</small></div></div><b class="${r.type==='in'?'c-in':'c-out'}">${r.type==='in'?'+':'-'}${fmt(r.amount,(wal(r.wallet)||{}).currency||P.currency)}</b></div><div class="row"><button class="lnk" data-act="editrec" data-id="${r.id}">Edit</button><button class="lnk" data-act="delrec" data-id="${r.id}">Hapus</button></div></div>`).join(''):empty('Belum ada transaksi rutin. Contoh: uang saku bulanan, tagihan internet, langganan.')}`;

const storageBytes=()=>Object.values(K).reduce((s,k)=>{const v=localStorage.getItem(K[k])||'';return s+new Blob([v]).size},0);const stor=()=>{const b=storageBytes();return b>=1048576?(b/1048576).toFixed(2).replace('.',',')+' MB':(b/1024).toFixed(2).replace('.',',')+' KB'};
/* ===== Laporan ===== */
function inRep(t){const d=t.date,m=ym(today());
  if(rp==='cur')return d.startsWith(m);if(rp==='prev')return d.startsWith(prevYm(m));
  if(rp==='3m')return[m,prevYm(m),shiftYm(m,-2)].includes(d.slice(0,7));
  if(rp==='year')return d.startsWith(today().slice(0,4));
  return(!RF.from||d>=RF.from)&&(!RF.to||d<=RF.to)}
const repTx=()=>D.tx.filter(inRep);
function dl(s,n,t){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([s],{type:t+';charset=utf-8'}));a.download=n;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1500)}
function exportCsv(){const rows=[['Tanggal','Waktu','Jenis','Nama','Kategori','Dompet','Ke dompet','Mata uang','Nominal','Memo']];
  sortTx(repTx()).forEach(t=>rows.push([t.date,t.time,{in:'Pemasukan',out:'Pengeluaran',tf:'Transfer'}[t.type],t.name,t.cat,(wal(t.wallet)||{}).name||'',(wal(t.to)||{}).name||'',cur(t),t.amount,t.memo]));
  const q=c=>'"'+String(c==null?'':c).replace(/^[=+\-@]/,"'$&").replace(/"/g,'""')+'"';
  dl('\ufeff'+rows.map(r=>r.map(q).join(',')).join('\r\n'),'duitku-laporan.csv','text/csv')}
function exportJson(){D.settings.lastBackup=Date.now();save('settings');const data={};for(const k in K)data[k]=D[k];dl(JSON.stringify({app:'duitku',version:1,exported:new Date().toISOString(),data},null,2),'duitku-backup.json','application/json')}
function validBackup(o){try{const d=o.data;if(o.app!=='duitku'||!d||!d.profile||typeof d.profile.name!=='string'||typeof d.profile.currency!=='string')return false;
  const ok=(a,fn)=>Array.isArray(a)&&a.every(x=>x&&typeof x.id==='string'&&fn(x));
  return ok(d.wallets,w=>typeof w.name==='string'&&typeof w.currency==='string'&&Number.isFinite(+w.initial))
   &&ok(d.tx,t=>['in','out','tf'].includes(t.type)&&typeof t.date==='string'&&Number.isFinite(t.amount)&&typeof t.wallet==='string')
   &&ok(d.budgets,b=>typeof b.cat==='string'&&Number.isFinite(b.limit))
   &&ok(d.goals,g=>Number.isFinite(g.target)&&Array.isArray(g.contribs))}catch(e){return false}}
function importJson(file){const r=new FileReader();r.onload=()=>{let o;try{o=JSON.parse(r.result)}catch(e){toast('File bukan JSON yang valid.','err');return}
  if(!validBackup(o)){toast('Struktur backup tidak valid. Data lama tidak diubah.','err');return}
  if(!confirm('Impor akan MENIMPA semua data saat ini. Lanjutkan?'))return;
  for(const k in K){D[k]=o.data[k]!==undefined?o.data[k]:DEF[k];save(k)}init();toast('Backup berhasil diimpor');go('dash')};r.readAsText(file)}


/* ===== Personalisasi, skor kesehatan keuangan, ekspor CSV (v2.1) ===== */
const ACC=[['emas','#f5b301','Emas','#d99a00'],['ios','#007aff','Biru iOS','#0062cc'],['ametis','#7c5cfc','Ametis','#6a49e8'],['safir','#3b6cf0','Safir','#2f59d4'],['lazuardi','#0ea5d9','Lazuardi','#0b8bb8'],['pirus','#0fb5ae','Pirus','#0c9690'],['petrol','#1f7a99','Petrol','#196480'],['nila','#5146e0','Nila','#4338c4'],['anggrek','#c04df0','Anggrek','#a43bd1'],['fuksia','#e02fa8','Fuksia','#bf2290'],['sakura','#ee6c9e','Sakura','#d4568a'],['baja','#5f7d9c','Baja','#4e6a87']];
const curAcc=()=>{const a=D.settings.accent;return a==='custom'||ACC.some(x=>x[0]===a)?a:ACC[0][0]};
const lum=h=>{const n=parseInt(h.slice(1),16),g=v=>{v/=255;return v<=.03928?v/12.92:Math.pow((v+.055)/1.055,2.4)};return .2126*g(n>>16&255)+.7152*g(n>>8&255)+.0722*g(n&255)};
const shade=(h,k)=>'#'+[16,8,0].map(x=>Math.max(0,Math.min(255,Math.round((parseInt(h.slice(1),16)>>x&255)*k))).toString(16).padStart(2,'0')).join('');
