  const a=g('age');if(!a)e.age='Usia wajib diisi.';else if(!/^\d+$/.test(a))e.age='Usia harus berupa bilangan bulat.';else if(+a<10)e.age='Usia minimal 10 tahun untuk menggunakan DuitKu.';else if(+a>120)e.age='Usia tidak valid.';
