function profileModal(){
  openModal('Edit profil',`<label>Foto profil<div class="avatar-options">${AVL.map(([a,n])=>`<label class="avatar-choice" title="${n}"><input type="radio" name="avatar" value="${a}" aria-label="${n}" ${P.avatar===a?'checked':''}><span>${avIc(a)}</span></label>`).join('')}</div><div class="avatar-up"><span class="avatar-up-preview">${P.avatar&&P.avatar.startsWith('data:image/')?`<img src="${P.avatar}" alt="">`:avIc(P.avatar||'user')}</span><label class="avatar-up-btn">Unggah foto<input type="file" id="avatarfile" accept="image/*" hidden></label></div><small class="muted">Pilih avatar atau unggah foto, lalu pangkas sesuai keinginan.</small></label><label>Nama lengkap<input name="name" value="${esc(P.name)}" maxlength="60"><small class="err"></small></label><label>Jenis kelamin<select name="gender">${opt('male',P.gender||'male','Laki-laki')}${opt('female',P.gender,'Perempuan')}${opt('secret',P.gender,'Rahasia')}</select></label>
      <label>Usia<input name="age" inputmode="numeric" value="${esc(P.age)}"><small class="err"></small></label>
  <label>Pekerjaan<select name="job">${JOBS.map(j=>opt(j,JOBS.includes(P.job)?P.job:'Lainnya')).join('')}</select></label><label>Agama<select name="religion">${RELIGIONS.map(([k,v])=>opt(k,P.religion||'secret',v)).join('')}</select></label><label>Jika "Lainnya", tulis pekerjaan<input name="jobOther" value="${JOBS.includes(P.job)?'':esc(P.job)}"><small class="err"></small></label>`,
  f=>{const er=validateProfile(f,false);showErrs(f,er);const k=Object.keys(er);if(k.length)return er[k[0]];
    const age=+gv(f,'age'),gender=gv(f,'gender')||P.gender||'male';P=D.profile={...P,avatar:avatarUpload||gv(f,'avatar')||defaultAvatar(age,gender),name:gv(f,'name').replace(/\s+/g,' '),age,gender,job:gv(f,'job')==='Lainnya'?gv(f,'jobOther'):gv(f,'job'),religion:gv(f,'religion')||P.religion||'secret'};
    return save('profile')?(toast('Profil diperbarui'),true):'Gagal menyimpan.'});const mf=$('#mf');if(mf){let auto=true;mf.querySelectorAll('[name=avatar]').forEach(r=>r.addEventListener('change',()=>auto=false));const syncAvatar=()=>{if(!auto)return;const id=defaultAvatar(+(mf.elements.age.value||P.age),mf.elements.gender.value||P.gender||'male'),r=mf.querySelector(`[name=avatar][value="${id}"]`);if(r)r.checked=true};mf.elements.gender.addEventListener('change',syncAvatar);mf.elements.age.addEventListener('input',syncAvatar);syncAvatar()}}
function startApp(){
  applyDue();
  if(!D.settings.termsAccepted){showTerms();return}
  launchDuitKu();
}
function showTerms(){
  $('#app').hidden=true;$('#onb').hidden=true;
  let layer=$('#termsGate');if(!layer){layer=document.createElement('section');layer.id='termsGate';document.body.appendChild(layer)}
  layer.innerHTML=`<div class="terms-shell"><div class="terms-brand"><div class="logo big dk-brand tb-lock"><span class="logo-mark" aria-hidden="true">${logoMark()}</span><span class="logo-col"><span class="logo-word"><span class="brand-d">D</span>uit<span class="brand-k">K</span>u</span><small class="logo-sub">SMART PERSONAL FINANCE</small></span></div>${themeSwitchHtml()}</div><div class="terms-copy"><span class="terms-kicker">SEBELUM MEMULAI</span><h1>Persetujuan penggunaan DuitKu</h1><p class="terms-lead">Baca poin penting berikut sebelum melanjutkan.</p><div class="terms-scroll"><h3>1. Tentang aplikasi ini</h3><p>DuitKu adalah aplikasi pencatat keuangan pribadi untuk membantu kamu mencatat transaksi, mengatur anggaran, menabung, dan memantau utang-piutang. Kamu masuk dengan email atau Google, dan DuitKu tidak meminta kartu atau akses ke rekening bank.</p><h3>2. Penyimpanan data</h3><p>Catatanmu disimpan di browser perangkat ini dan disalin ke akunmu agar bisa dilanjutkan di perangkat lain. Mereset aplikasi menghapus data di akun dan di perangkat. Tetap buat backup JSON secara berkala.</p><h3>3. Privasi dan DuitKu Intelligence</h3><p>DuitKu Intelligence, Wrapped, dan Mini Games dihitung di perangkatmu dari data yang tersimpan di browser ini. Fitur tersebut tidak mengirim data ke layanan AI atau pihak ketiga. Jangan memasukkan kata sandi, PIN, nomor kartu, atau data sensitif lain ke catatan transaksi.</p><h3>4. Bukan nasihat keuangan</h3><p>DuitKu adalah alat bantu pencatatan dan edukasi, bukan bank, lembaga keuangan, atau penasihat profesional. Saran, insight, dan hasil perhitungan bersifat umum dan bergantung pada data yang kamu masukkan. Periksa kembali angka sebelum mengambil keputusan penting seperti berutang, berinvestasi, atau menarik tabungan.</p><h3>5. Keakuratan data</h3><p>Kamu bertanggung jawab atas kebenaran nominal, tanggal, kategori, dan dompet yang dicatat. Kesalahan input akan memengaruhi saldo, statistik, laporan, dan peringatan anggaran. Kamu dapat mengubah atau menghapus catatan kapan saja.</p><h3>6. Keamanan perangkat</h3><p>PIN aplikasi hanya mengunci tampilan dan bukan enkripsi. Gunakan perangkat pribadi, aktifkan kunci layar, dan jangan membiarkan orang lain memakai browser yang menyimpan data DuitKu. Jika lupa PIN, satu-satunya jalan adalah mereset aplikasi.</p><h3>7. Hak kekayaan intelektual</h3><p>Nama, logo, tampilan, dan kode DuitKu dilindungi hak cipta oleh pengembangnya. Kamu boleh memakai aplikasi ini untuk keperluan pribadi dan pembelajaran, tetapi tidak boleh menyalin, menjual, atau mengklaimnya sebagai karya sendiri tanpa izin.</p><h3>8. Perubahan dan pilihanmu</h3><p>Fitur dan ketentuan dapat diperbarui seiring pengembangan. Dengan memilih “Saya setuju”, kamu menyatakan telah membaca, memahami, dan menerima seluruh poin di atas. Jika tidak setuju, kamu dapat kembali dan tidak melanjutkan penggunaan aplikasi.</p></div><div class="terms-confirm-row"><span class="terms-confirm-copy"><b>Saya sudah membaca ketentuan</b><small>Aktifkan tombol ini untuk menyatakan persetujuan dan melanjutkan.</small></span><button type="button" id="termsConfirmSwitch" class="terms-confirm-switch" role="switch" aria-checked="false" aria-label="Saya sudah membaca dan menyetujui ketentuan"><span></span></button></div><div class="terms-actions"><button class="btn ghost" data-terms="no">Tidak setuju</button><button class="btn terms-accept" data-terms="yes" disabled aria-disabled="true">Saya setuju & lanjutkan <span>→</span></button></div><button type="button" class="terms-back" data-terms="back"><svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M15 5l-7 7 7 7"/></svg>Kembali ke langkah sebelumnya</button><p class="terms-foot">Persetujuan ini disimpan di browser perangkat ini dan dapat ditinjau lagi melalui Pengaturan.</p></div></div>`;enhanceTerms(layer);
  layer.hidden=false;
}
function launchDuitKu(){if(D.settings.hideOnStart&&!window.__hs){window.__hs=1;D.settings.hide=true;save('settings')}
  const tg=$('#termsGate');if(tg)tg.hidden=true;
  $('#app').hidden=false;$('#app').classList.remove('fade');void $('#app').offsetWidth;$('#app').classList.add('fade');ENTER=true;render();
  if(!D.settings.welcomed){const w=document.createElement('div');w.className='dk-welcome';w.innerHTML=welcomeHtml();document.body.appendChild(w);placeFin(w);w.onclick=()=>{w.classList.add('leave');setTimeout(()=>w.remove(),650);D.settings.welcomed=true;save('settings')};setTimeout(()=>{w.classList.add('leave');setTimeout(()=>w.remove(),650);D.settings.welcomed=true;save('settings')},14000)}
  document.body.classList.remove('welcome-pop');void document.body.offsetWidth;document.body.classList.add('welcome-pop');clearTimeout(startApp.welcomeTimer);startApp.welcomeTimer=setTimeout(()=>document.body.classList.remove('welcome-pop'),4200)
}

