function payload(k){let v=D[k];if(k==='settings'){v={...v};LOCAL_ONLY.forEach(f=>delete v[f])}return JSON.stringify(v)}
function writeLocalKey(k,json){let v;try{v=JSON.parse(json)}catch(e){return}
 if(k==='settings'){let loc={};try{loc=JSON.parse(localStorage.getItem(K.settings))||{}}catch(e){}LOCAL_ONLY.forEach(f=>{if(f in loc)v[f]=loc[f]});if(!('theme' in v)){v.themeAuto=true;v.theme=matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'}}
 localStorage.setItem(K[k],JSON.stringify(v))}
