async function pushKey(k){const s=payload(k);if(lastPushed[k]!==s){const m=syncMeta();await dataCol().doc(k).set({json:s,t:m.t[k]||Date.now()});lastPushed[k]=s}const m2=syncMeta();m2.dirty=m2.dirty.filter(x=>x!==k);saveMeta(m2)}
