function schedulePush(k){const m=syncMeta();m.t[k]=Date.now();if(!m.dirty.includes(k))m.dirty.push(k);saveMeta(m);syncState='syncing';updSync();clearTimeout(pushT);pushT=setTimeout(flush,1200)}
const _save=save;save=function(k){const r=_save(k);if(r&&CU&&SYNC_KEYS.includes(k))schedulePush(k);return r};
async function syncDown(){syncState='syncing';const snap=await withTimeout(dataCol().get(),9000),docs={};snap.forEach(d=>docs[d.id]=d.data());
 let m=syncMeta();if(m.uid&&m.uid!==CU.uid){wipeLocal();m={uid:'',t:{},dirty:[]}}
 if(!m.uid&&docs.profile&&localStorage.getItem(K.profile)){const b={};Object.values(K).forEach(k=>b[k]=localStorage.getItem(k));try{localStorage.setItem('duitku_pre_sync_backup',JSON.stringify(b))}catch(e){}}
 SYNC_KEYS.forEach(k=>{const c=docs[k],lt=m.t[k]||0,has=localStorage.getItem(K[k])!=null;
  if(c&&c.t>lt){writeLocalKey(k,c.json);m.t[k]=c.t;m.dirty=m.dirty.filter(x=>x!==k)}
  else if(has&&(!c||lt>c.t)&&!m.dirty.includes(k)){m.t[k]=lt||Date.now();m.dirty.push(k)}});
 m.uid=CU.uid;saveMeta(m);init();await flush()}
