  const s=c.series(6).filter(x=>x.I>0);if(s.length<3)return need('Butuh minimal 3 bulan dengan pemasukan untuk melihat tren.',['Lengkapi pencatatan pemasukan dan pengeluaran selama beberapa bulan.']);
