  if(ov.length)L.push([3,'Tinjau anggaran yang terlampaui',ov.map(b=>b.cat).join(', ')]);
  if(c.liquid<0)L.push([2,'Saldo dompet negatif','Total saldo dompet aktif '+F(c.liquid)+'; periksa transaksi atau tambah dana']);
