  const W=Array(7).fill(0),Wc=Array(7).fill(0);c.out.forEach(t=>{W[wd(t.date)]+=t.amount});for(let i=0;i<c.days;i++)Wc[wd(addD(c.pr.from,i))]++;
  const pm=[0,0,0];c.out.forEach(t=>{const d=+t.date.slice(8);pm[d<=10?0:d<=20?1:2]+=t.amount});
