  const pace=el>=3?sofar/el*dm:null,byH=hist.n?sofar+hist.v/dm*left:null,vals=[pace,byH].filter(v=>v!=null),bl=avg(vals),tb=sumA(D.budgets.filter(b=>b.month===m0).map(b=>({amount:b.limit})));
