  const c=mkCtx('cur'),b=c.budStat().filter(x=>x.limit>0),L=sumA(b.map(x=>({amount:x.limit}))),U=sumA(b.map(x=>({amount:x.used}))),gs=c.goalStats(),r=pc(c.O,c.I);
