function smartHtml(){return `<div class="ismart"><button type="button" class="card ismart-c" data-act="intelopen" data-k="guard"><span class="ismart-ic">${ic('shield',24)}</span><div><b>Smart Spend Guard</b><small>Periksa rencana pembelian: aman atau perlu ditunda, berdasarkan saldo, tagihan, anggaran, dan kebiasaanmu.</small></div></button><button type="button" class="card ismart-c" data-act="intelopen" data-k="planner"><span class="ismart-ic">${ic('goal',24)}</span><div><b>Smart Goal Planner</b><small>Rencanakan target tabungan: berapa per bulan, kapan selesai, dan bagaimana membagi dana antar target.</small></div></button></div>`}

/* ---------- panel hasil ---------- */
const mtx=(m)=>`<div class="imetrics">${m.map(([l,v,t])=>`<div class="imetric ${t||''}"><small>${esc(String(l))}</small><b>${esc(String(v))}</b></div>`).join('')}</div>`;
const tbl=t=>`<div class="itbl-w"><table class="itbl"><thead><tr>${t.head.map(h=>`<th>${esc(String(h))}</th>`).join('')}</tr></thead><tbody>${t.body.map(r=>`<tr>${r.map(x=>`<td>${esc(String(x))}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
